function routeMarksStation(id,exceptRouteId=''){return routes.some(r=>r.id!==exceptRouteId&&(r.runStarted||(r.completed||[]).length>0)&&!r.returnedHome&&(r.completed||[]).includes(id))}
function reconcileRouteVisit(id){let s=getStation(id);if(!s||id===HOME_BASE_ID)return;if(routeMarksStation(id)){s.status='done';return}if(typeof s.routeVisitWasDone==='boolean'){s.status=s.routeVisitWasDone?'done':'todo';if(!s.routeVisitWasDone)delete s.visitedAt;delete s.routeVisitWasDone}}
function toggleStatus(id){let s=getStation(id);if(!s||id===HOME_BASE_ID)return;if(routeMarksStation(id)){alert('Undo this station on its completed route before changing its visit status.');return}s.status=s.status==='done'?'todo':'done';if(s.status==='done')s.visitedAt=new Date().toISOString();else delete s.visitedAt;renderAll()}
function setCurrent(id){current=getStation(id)?id:'';if(current&&current!==HOME_BASE_ID){let s=getStation(current);s.status='done';s.visitedAt=s.visitedAt||new Date().toISOString();if(routeMarksStation(current))s.routeVisitWasDone=true}save();renderAll()}
function resetStatuses(){if(!confirm('Reset every station to Not Visited? This does not delete your routes.'))return;stations.forEach(s=>{s.status=s.id===HOME_BASE_ID?'done':'todo';delete s.visitedAt;delete s.routeVisitWasDone});current='';routes.forEach(r=>{r.completed=[];r.returnedHome=false;r.runStarted=false;r.atHomeForDropoff=false;r.earlyDropoffs=[]});renderAll()}
function openStationModal(){document.getElementById('stationForm').reset();document.getElementById('editStationId').value='';document.getElementById('stationModalTitle').textContent='Add station';document.getElementById('stationStatus').value='todo';document.getElementById('stationModal').classList.add('open')}
function editStation(id){let s=getStation(id);if(!s||id===HOME_BASE_ID){if(id===HOME_BASE_ID)alert('Ruin Station is the fixed home base and cannot be edited.');return}document.getElementById('stationForm').reset();document.getElementById('editStationId').value=id;document.getElementById('stationName').value=s.name;document.getElementById('stationType').value=s.type;document.getElementById('stationStatus').value=s.status;document.getElementById('stationNotes').value=s.notes||'';document.getElementById('stationModalTitle').textContent='Edit station';document.getElementById('stationModal').classList.add('open')}
document.getElementById('stationForm').onsubmit=e=>{e.preventDefault();let id=document.getElementById('editStationId').value,name=document.getElementById('stationName').value.trim();if(id===HOME_BASE_ID){alert('Ruin Station is the fixed home base and cannot be edited.');return}if(!name)return;if(stations.some(s=>s.name.toLowerCase()===name.toLowerCase()&&s.id!==id)){alert('A station with that name already exists.');return}let data={name,type:document.getElementById('stationType').value,status:document.getElementById('stationStatus').value,notes:document.getElementById('stationNotes').value.trim()};if(id)Object.assign(getStation(id),data);else stations.push({id:'station-'+Date.now(),...data});closeModal('stationModal');renderAll()};
function deleteStation(id){let s=getStation(id);if(!s||id===HOME_BASE_ID||!confirm('Delete '+s.name+'? This also removes it from saved routes.'))return;stations=stations.filter(x=>x.id!==id);routes.forEach(r=>{r.stops=r.stops.filter(x=>x!==id);r.completed=(r.completed||[]).filter(x=>x!==id);if(r.deliveryStationId===id){r.deliveryStationId=HOME_BASE_ID;r.returnedHome=false;r.active=false;if(r.atHomeForDropoff&&current===id)current=HOME_BASE_ID}});if(current===id)current='';renderAll()}
function openRouteModal(){document.getElementById('routeForm').reset();document.getElementById('routeStart').innerHTML='<option value="ruin-station">Ruin Station (fixed home base)</option>';document.getElementById('routeDeliveryStation').innerHTML=routeDestinationOptions(HOME_BASE_ID);document.getElementById('routeTypeFilter').value='all';routeDraftStops=new Set(stations.filter(s=>s.id!==HOME_BASE_ID).map(s=>s.id));renderRoutePicks();document.getElementById('routeModal').classList.add('open')}
function renderRoutePicks(){let f=document.getElementById('routeTypeFilter').value,q=document.getElementById('routeStationSearch').value.trim().toLowerCase();let list=stations.filter(s=>s.id!==HOME_BASE_ID&&(f==='all'||s.type===f)&&s.name.toLowerCase().includes(q));document.getElementById('routePicks').innerHTML=list.map(s=>`<label class="pick ${routeDraftStops.has(s.id)?'selected':''}"><input type="checkbox" value="${esc(s.id)}" ${routeDraftStops.has(s.id)?'checked':''} onchange="setRouteDraftStop('${esc(s.id)}',this.checked)"><span>${esc(s.name)}<small style="display:block;color:var(--muted)">${s.type==='external'?'External elevator':'Regular station'}</small></span></label>`).join('')||'<span class="muted">No stations match this search.</span>';document.getElementById('routeSelectionCount').textContent=`${routeDraftStops.size} stations selected`}
function setRouteDraftStop(id,selected){if(selected)routeDraftStops.add(id);else routeDraftStops.delete(id);document.getElementById('routeSelectionCount').textContent=`${routeDraftStops.size} stations selected`;document.querySelector(`#routePicks input[value="${CSS.escape(id)}"]`)?.closest('.pick').classList.toggle('selected',selected)}
document.getElementById('routeForm').onsubmit=e=>{e.preventDefault();let stops=stations.filter(s=>routeDraftStops.has(s.id)&&s.id!==HOME_BASE_ID).map(s=>s.id);if(!stops.length){alert('Select at least one station to visit.');return}let r={id:'route-'+Date.now(),name:document.getElementById('routeName').value.trim(),deliveryStationId:stations.some(s=>s.id===document.getElementById('routeDeliveryStation').value)?document.getElementById('routeDeliveryStation').value:HOME_BASE_ID,stops,completed:[],returnedHome:false,runStarted:false,active:false,atHomeForDropoff:false,earlyDropoffs:[]};routes.push(r);activeRoute=r.id;closeModal('routeModal');renderAll();showPage('routes')};
function openFeatureRequest(){feedbackTriggerElement=document.activeElement;showRequestForm();document.getElementById('featureRequestForm').reset();setFeedbackStatus('','');document.getElementById('featureRequestModal').classList.add('open');document.getElementById('featureRequestTitle').focus()}
function feedbackApiUrl(){const configured=window.PYRONAV_FEEDBACK_API_URL;if(typeof configured!=='string'||!configured.trim())throw new Error('Feedback service is not configured in this app yet. Your request has not been sent.');return configured.trim().replace(/\/+$/,'')}
async function feedbackFetch(path,options={},expectedStatus){const base=feedbackApiUrl();let response;try{response=await fetch(base+path,options)}catch{throw new Error('Could not reach the feedback service. Check your connection and try again.')}if(!response.ok){let detail='';try{const body=await response.json();detail=body&&typeof body.error==='string'?` ${body.error}`:''}catch{}throw new Error(`The feedback service returned an error (${response.status}).${detail} Please try again.`)}if(expectedStatus&&response.status!==expectedStatus)throw new Error(`The feedback service returned an unexpected response (${response.status}). Please try again.`);return response}
function setFeedbackStatus(message,state){const status=document.getElementById('featureRequestStatus');status.textContent=message;status.className='feedback-status'+(state?' '+state:'');status.hidden=!message}
function setOwnerStatus(message,state){const status=document.getElementById('ownerInboxStatus');status.textContent=message;status.className='inbox-status'+(state?' '+state:'');status.hidden=!message}
function showOwnerInbox(){ownerInboxToken='';ownerRequests=[];document.getElementById('ownerToken').value='';document.getElementById('ownerRequests').innerHTML='';setOwnerStatus('','');document.getElementById('ownerInboxRefresh').hidden=true;document.getElementById('requestView').hidden=true;document.getElementById('ownerInboxView').hidden=false;document.getElementById('ownerToken').focus()}
function showRequestForm(){document.getElementById('requestView').hidden=false;document.getElementById('ownerInboxView').hidden=true;ownerInboxToken='';ownerRequests=[];document.getElementById('ownerToken').value='';document.getElementById('ownerRequests').innerHTML='';setOwnerStatus('','');document.getElementById('featureRequestTitle').focus()}
async function sendFeatureRequest(event){event.preventDefault();const form=document.getElementById('featureRequestForm'),submit=document.getElementById('featureRequestSubmit'),title=document.getElementById('featureRequestTitle').value.trim(),details=document.getElementById('featureRequestDetails').value.trim();if(!title||!details)return;submit.disabled=true;submit.textContent='Sending…';setFeedbackStatus('Sending request…','is-pending');try{const response=await feedbackFetch('/api/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title,details})},201);let result;try{result=await response.json()}catch{throw new Error('The service did not confirm that your request was stored. Your draft is still here; please retry.')}if(!result||typeof result.id!=='string'||!result.id.trim())throw new Error('The service did not confirm that your request was stored. Your draft is still here; please retry.');form.reset();setFeedbackStatus(`Request received and stored. Reference: ${result.id}`,'is-success')}catch(error){setFeedbackStatus(error.message,'is-error')}finally{submit.disabled=false;submit.textContent='Send request'}}
async function unlockOwnerInbox(event){event.preventDefault();const token=document.getElementById('ownerToken').value.trim(),button=document.getElementById('ownerUnlockButton');if(!token)return;ownerInboxToken=token;button.disabled=true;button.textContent='Checking…';setOwnerStatus('Checking owner access…','is-pending');try{await loadOwnerRequests()}finally{button.disabled=false;button.textContent='Unlock inbox'}}
async function loadOwnerRequests(){if(!ownerInboxToken){setOwnerStatus('Enter the owner token to unlock this inbox.','is-error');return}const refresh=document.getElementById('ownerInboxRefresh');refresh.disabled=true;refresh.textContent='Loading…';setOwnerStatus('Loading private requests…','is-pending');document.getElementById('ownerRequests').innerHTML='';try{const response=await feedbackFetch('/api/requests',{headers:{Authorization:`Bearer ${ownerInboxToken}`}},200),payload=await response.json();if(!payload||!Array.isArray(payload.requests)||payload.requests.some(request=>!request||typeof request.id!=='string'||typeof request.title!=='string'||typeof request.details!=='string'||typeof request.createdAt!=='string'||!['new','reviewed'].includes(request.status)))throw new Error('The inbox response was not in the expected format. Try refreshing.');ownerRequests=payload.requests;renderOwnerRequests();setOwnerStatus(ownerRequests.length?`${ownerRequests.length} private request${ownerRequests.length===1?'':'s'} loaded.`:'No requests have been submitted yet.','');refresh.hidden=false}catch(error){ownerRequests=[];setOwnerStatus(error.message,'is-error')}finally{refresh.disabled=false;refresh.textContent='Refresh'}}
function renderOwnerRequests(){const list=document.getElementById('ownerRequests');list.innerHTML=ownerRequests.length?ownerRequests.map(request=>`<article class="request-card"><div class="request-card-heading"><h4>${esc(request.title)}</h4><span class="badge ${request.status==='new'?'todo':'done'}">${request.status==='new'?'NEW':'REVIEWED'}</span></div><p>${esc(request.details)}</p><div class="request-card-foot"><time datetime="${esc(request.createdAt)}">${esc(new Date(request.createdAt).toLocaleString())}</time>${request.status==='new'?`<button type="button" class="review-request" data-request-id="${esc(request.id)}">Mark reviewed</button>`:''}</div></article>`).join(''):'<div class="empty">No requests have been submitted yet.</div>';list.querySelectorAll('.review-request').forEach(button=>button.onclick=()=>markRequestReviewed(button.dataset.requestId,button))}
async function markRequestReviewed(id,button){if(!ownerInboxToken)return;button.disabled=true;button.textContent='Updating…';setOwnerStatus('Updating request status…','is-pending');try{await feedbackFetch('/api/requests/'+encodeURIComponent(id),{method:'PATCH',headers:{Authorization:`Bearer ${ownerInboxToken}`,'Content-Type':'application/json'},body:JSON.stringify({status:'reviewed'})},200);ownerRequests=ownerRequests.map(request=>request.id===id?{...request,status:'reviewed'}:request);renderOwnerRequests();setOwnerStatus('Request marked reviewed.','is-success')}catch(error){setOwnerStatus(error.message,'is-error');button.disabled=false;button.textContent='Mark reviewed'}}
function renderRoutes(){
 document.getElementById('routeCountTag').textContent=routes.length+' ROUTES';
 document.getElementById('routeCards').innerHTML=routes.map(r=>`<div class="route-stop" style="${r.id===activeRoute?'border-color:var(--accent-hover)':''}"><div class="num">⌁</div><div><strong>${esc(r.name)}</strong><small>${r.stops.length} stops · ${(r.completed||[]).length} route stops complete · ${r.active?'ACTIVE':'PAUSED'} · Deliver to ${esc(routeDestinationName(r))}</small><small class="route-card-distance">${esc(formatRouteDistance(getRouteDistanceSummary(r)))}</small></div><div class="stopactions"><button onclick="focusRoute('${r.id}')">${r.id===activeRoute?'Focused':'Focus'}</button><button onclick="toggleRouteActive('${r.id}')">${r.active?'Pause':'Activate'}</button><button onclick="deleteRoute('${r.id}')" class="danger">×</button></div></div>`).join('')||'<div class="empty">No saved routes. Create one to begin planning.</div>';
 let r=routes.find(x=>x.id===activeRoute);
 if(!r){document.getElementById('activeRoutePanel').innerHTML='<div class="empty">Choose a saved route or create a new one.</div>';return}
 const destination=routeDestinationId(r),destinationName=routeDestinationName(r);
 document.getElementById('activeRoutePanel').innerHTML=`<div class="eyebrow" style="margin-bottom:5px">FOCUSED ITINERARY · ${r.active?'ACTIVE':'PAUSED'}</div><h3 style="font-size:19px;margin:0 0 5px">${esc(r.name)}</h3><div class="muted" style="font-size:11px;margin-bottom:12px">${(r.completed||[]).length} / ${r.stops.length} selected stops complete</div><div class="progress"><div style="width:${r.stops.length?Math.round((r.completed||[]).length/r.stops.length*100):0}%"></div></div><label class="field" style="display:block;margin:12px 0"><span>DELIVERY / PIT-STOP LOCATION</span><select onchange="setRouteDeliveryStation('${r.id}',this.value)" ${r.atHomeForDropoff?'disabled':''}>${routeDestinationOptions(destination)}</select><small class="muted">${r.atHomeForDropoff?'Continue this pit stop before changing its delivery location.':'Ruin Station remains the fixed departure point.'}</small></label><div class="route-list"><div class="route-stop"><div class="num">⌂</div><div><strong>Ruin Station</strong><small>HOME BASE · DEPARTURE</small></div><span class="badge done">START</span></div>${r.stops.map((id,i)=>{let s=getStation(id),done=(r.completed||[]).includes(id);if(!s)return'';let prev=i===0?((r.completed||[]).length===0&&getStation(current)?current:HOME_BASE_ID):r.stops[i-1],d=dist(prev,id),origin=i===0&&(r.completed||[]).length===0&&current&&current!==HOME_BASE_ID?'from current station':'from previous stop';return `<div class="route-stop ${done?'completed':''}"><div class="num">${done?'✓':String(i+1).padStart(2,'0')}</div><div><strong>${esc(s.name)}</strong><small>${s.type==='external'?'External freight elevator':'Regular station'} · ${fmtDist(d)} ${origin}</small></div><div class="stopactions"><button onclick="moveStop('${r.id}',${i},-1)" ${i===0?'disabled':''}>↑</button><button onclick="moveStop('${r.id}',${i},1)" ${i===r.stops.length-1?'disabled':''}>↓</button><button onclick="toggleRouteStop('${r.id}','${id}')">${done?'Undo':'Done'}</button></div></div>`}).join('')}<div class="route-stop ${r.returnedHome?'completed':''}"><div class="num">${r.returnedHome?'✓':'↩'}</div><div><strong>${esc(destinationName)}</strong><small>DELIVERY DESTINATION · FINAL DROP-OFF</small></div><div class="stopactions"><button onclick="toggleReturnHome('${r.id}')">${r.returnedHome?'Undo delivery':'Delivered'}</button></div></div></div><div class="actions" style="margin-top:12px"><button onclick="optimizeRoute('${r.id}')">Optimize order</button><button onclick="clearRouteProgress('${r.id}')">Reset route progress</button></div><div class="note">Routes always depart from Ruin Station and finish at the selected delivery location. Optimize order keeps completed stops fixed and includes the delivery leg when distances are known. Review the route before flying.</div>`
}
function renderRouteChecklist(){
 const route=routes.find(item=>item.id===activeRoute),panel=document.getElementById('activeRoutePanel');
 if(!panel)return;
 if(!route)return;
 const destination=routeDestinationName(route),destinationId=routeDestinationId(route),started=route.runStarted||(route.completed||[]).length>0||route.returnedHome,completed=new Set(route.completed||[]),next=route.stops.find(id=>!completed.has(id)),distance=getRouteDistanceSummary(route),missing=distance.unknown.map(([from,to])=>`${getStation(from)?.name||from} → ${getStation(to)?.name||to}`).join(', '),lastDrop=route.earlyDropoffs?.[route.earlyDropoffs.length-1],dropDetail=lastDrop?`Early drop #${route.earlyDropoffs.length} delivered to ${getStation(lastDrop.deliveryStationId||route.deliveryStationId)?.name||destination} from ${getStation(lastDrop.stationId)?.name||'your previous location'} · ${lastDrop.completedStops} stops completed so far.`:'';
 const action=route.atHomeForDropoff?`Early drop-off recorded at ${destination} · ${next?'continue to '+(getStation(next)?.name||'next stop'):'all stops complete'}`:!started?'Ready to depart from Ruin Station':next?`Next stop: ${getStation(next)?.name||'Unavailable station'}`:route.returnedHome?'Haul run complete':`All stops complete · deliver to ${destination}`;
 const checklist=`<div class="haul-checklist"><div class="haul-checklist-head"><div><div class="eyebrow">HAUL RUN CHECKLIST</div><strong>${esc(action)}</strong></div><span class="badge ${route.returnedHome?'done':route.atHomeForDropoff?'current':started?'current':''}">${route.returnedHome?'COMPLETE':route.atHomeForDropoff?'PIT STOP AT '+esc(destination).toUpperCase():started?'IN PROGRESS':'READY'}</span></div>${route.atHomeForDropoff?`<div class="early-drop-detail">${esc(dropDetail)}</div>`:''}<div class="haul-distance"><span>Remaining estimate</span><strong>${esc(formatRouteDistance(distance))}</strong></div>${distance.unknown.length?`<div class="haul-warning">${esc(missing)} <button onclick="showPage('distances')">Add distances</button></div>`:''}<div class="haul-checklist-actions">${route.atHomeForDropoff?`<button class="primary" onclick="continueAfterEarlyDropoff('${route.id}')">Continue route from ${esc(destination)}</button>`:started?`<button onclick="startFreshHaulRun('${route.id}')">Start fresh run</button>${route.active&&next&&current!==destinationId?`<button onclick="recordEarlyDropoff('${route.id}')">Pit stop at ${esc(destination)}</button>`:''}`:`<button class="primary" onclick="startHaulRun('${route.id}')">Start haul run</button>`}${started&&!route.returnedHome&&!route.atHomeForDropoff&&!next?`<button class="primary" onclick="toggleReturnHome('${route.id}')">Complete delivery at ${esc(destination)}</button>`:''}</div></div>`;
 const stopList=panel.querySelector('.route-list');
 if(stopList)stopList.insertAdjacentHTML('beforebegin',checklist);
}
function focusRoute(id){activeRoute=routes.some(route=>route.id===id)?id:'';save();renderAll()}
function activateRoute(id){let route=routes.find(item=>item.id===id);if(!route)return;route.active=true;activeRoute=id;save();renderAll()}
function toggleRouteActive(id){let route=routes.find(item=>item.id===id);if(!route)return;if(!route.active&&route.returnedHome){alert('This haul run is complete. Start a fresh run from the focused route to activate it again.');return}route.active=!route.active;if(route.active)activeRoute=id;save();renderAll()}
function openRoutePlan(id){focusRoute(id);showPage('routes')}
function deleteRoute(id){let route=routes.find(r=>r.id===id);if(!route||!confirm('Delete this route?'))return;let completed=[...(route.completed||[])];routes=routes.filter(r=>r.id!==id);if(activeRoute===id)activeRoute=routes[0]?.id||'';completed.forEach(reconcileRouteVisit);renderAll()}
function setRouteDeliveryStation(rid,stationId){let route=routes.find(item=>item.id===rid);if(!route)return;if(route.atHomeForDropoff){alert('Continue the current pit stop before changing its delivery location.');renderRoutes();renderRouteChecklist();return}if(!getStation(stationId)){renderRoutes();return}if(route.deliveryStationId===stationId)return;route.deliveryStationId=stationId;if(route.returnedHome){route.returnedHome=false;route.active=false}renderAll()}
function moveStop(rid,i,delta){let r=routes.find(x=>x.id===rid),j=i+delta;if(!r||j<0||j>=r.stops.length)return;[r.stops[i],r.stops[j]]=[r.stops[j],r.stops[i]];renderAll()}
function startHaulRun(rid){let r=routes.find(x=>x.id===rid);if(!r)return;r.runStarted=true;r.active=true;r.returnedHome=false;r.atHomeForDropoff=false;if(!getStation(current))current=HOME_BASE_ID;activeRoute=rid;renderAll()}
function startFreshHaulRun(rid){let r=routes.find(x=>x.id===rid);if(!r||!confirm('Start a fresh haul run? This clears this route’s stop and return progress but keeps the saved route.'))return;let completed=[...(r.completed||[])];r.completed=[];r.returnedHome=false;r.runStarted=true;r.active=true;r.atHomeForDropoff=false;r.earlyDropoffs=[];completed.forEach(reconcileRouteVisit);current=HOME_BASE_ID;activeRoute=rid;renderAll()}
function recordEarlyDropoff(rid){let r=routes.find(x=>x.id===rid),destination=routeDestinationId(r||{});if(!r||!r.runStarted||!r.active||r.returnedHome||r.atHomeForDropoff||current===destination)return;r.earlyDropoffs=r.earlyDropoffs||[];r.earlyDropoffs.push({stationId:getStation(current)?current:null,deliveryStationId:destination,completedStops:(r.completed||[]).length,at:new Date().toISOString()});r.atHomeForDropoff=true;current=destination;activeRoute=rid;renderAll()}
function continueAfterEarlyDropoff(rid){let r=routes.find(x=>x.id===rid);if(!r||!r.atHomeForDropoff||r.returnedHome)return;r.atHomeForDropoff=false;r.runStarted=true;r.active=true;current=routeDestinationId(r);activeRoute=rid;renderAll()}
function toggleRouteStop(rid,id){let r=routes.find(x=>x.id===rid);if(!r)return;r.completed=r.completed||[];if(r.completed.includes(id)){r.completed=r.completed.filter(x=>x!==id);r.returnedHome=false;reconcileRouteVisit(id);if(current===id&&getStation(id)?.status==='todo'){let index=r.stops.indexOf(id);current=r.stops.slice(0,index).reverse().find(stop=>(r.completed||[]).includes(stop))||HOME_BASE_ID}}else{if(r.atHomeForDropoff){alert(`Continue the route from ${routeDestinationName(r)} before completing another stop.`);return}if(!r.active){alert('Activate this route before checking off route stops.');return}if(!r.runStarted&&!(r.completed||[]).length){alert('Start the haul run before checking off route stops.');return}const nextStop=r.stops.find(stop=>!r.completed.includes(stop));if(nextStop!==id){alert(`Complete ${getStation(nextStop)?.name||'the next route stop'} first to keep the haul run in order.`);return}let s=getStation(id);if(s&&!routeMarksStation(id))s.routeVisitWasDone=s.status==='done';r.completed.push(id);if(s){s.status='done';s.visitedAt=s.visitedAt||new Date().toISOString()}current=id;r.returnedHome=false}renderAll()}
function toggleReturnHome(rid){let r=routes.find(x=>x.id===rid);if(!r)return;if(r.returnedHome){r.returnedHome=false;r.active=true;r.runStarted=true;r.atHomeForDropoff=false;(r.completed||[]).forEach(id=>{let s=getStation(id);if(!s||id===HOME_BASE_ID||routeMarksStation(id,r.id))return;s.routeVisitWasDone=s.status==='done';s.status='done';s.visitedAt=s.visitedAt||new Date().toISOString()})}else{if(r.atHomeForDropoff){alert('Continue or finish the pit stop before recording final delivery.');return}if(!r.active){alert('Activate this route before recording delivery.');return}if(!r.runStarted&&!(r.completed||[]).length){alert('Start the haul run before recording delivery.');return}if(!r.stops.every(id=>(r.completed||[]).includes(id))){alert('Complete every route stop before recording delivery.');return}r.returnedHome=true;r.atHomeForDropoff=false;r.active=false;current=routeDestinationId(r);(r.completed||[]).forEach(reconcileRouteVisit)}renderAll()}
function clearRouteProgress(rid){let r=routes.find(x=>x.id===rid);if(r){let completed=[...(r.completed||[])];r.completed=[];r.returnedHome=false;r.runStarted=false;r.atHomeForDropoff=false;r.earlyDropoffs=[];r.active=false;completed.forEach(reconcileRouteVisit)}current=HOME_BASE_ID;renderAll()}
function routeCost(start,order,route){let total=0,from=start;for(const id of order){let leg=dist(from,id);if(leg==null)return null;total+=leg;from=id}let finalLeg=dist(from,routeDestinationId(route));return finalLeg==null?null:total+finalLeg}
function optimizeRoute(rid){
 let r=routes.find(x=>x.id===rid);if(!r||r.stops.length<2)return;
 let completed=new Set(r.completed||[]),done=r.stops.filter(id=>completed.has(id)),remaining=r.stops.filter(id=>!completed.has(id));
 if(!remaining.length)return;
 let start=getStation(current)?current:(done.length?done[done.length-1]:HOME_BASE_ID);
 let order=[];
 while(remaining.length){
  let from=order.length?order[order.length-1]:start;
  let candidates=remaining.map((id,index)=>({id,index,d:dist(from,id)})).filter(x=>x.d!=null).sort((a,b)=>a.d-b.d||a.index-b.index);
  let next=candidates.length?candidates[0].id:remaining[0];
  order.push(next);remaining=remaining.filter(id=>id!==next);
 }
 let bestCost=routeCost(start,order,r);
 if(bestCost!==null){
  let improved=true;
  while(improved){
   improved=false;
   for(let i=0;i<order.length-1&&!improved;i++)for(let j=i+1;j<order.length;j++){
    let candidate=[...order.slice(0,i),...order.slice(i,j+1).reverse(),...order.slice(j+1)],cost=routeCost(start,candidate,r);
    if(cost!==null&&cost<bestCost){order=candidate;bestCost=cost;improved=true;break}
   }
  }
 }
 r.stops=[...done,...order];r.returnedHome=false;activeRoute=rid;renderAll()
}
function openDistanceModal(){let opts=stations.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');document.getElementById('distanceFrom').innerHTML=opts;document.getElementById('distanceTo').innerHTML=opts;document.getElementById('distanceValue').value='';document.getElementById('distanceModal').classList.add('open')}
document.getElementById('distanceForm').onsubmit=e=>{e.preventDefault();let a=document.getElementById('distanceFrom').value,b=document.getElementById('distanceTo').value,v=Number(document.getElementById('distanceValue').value);if(a===b){alert('Choose two different stations.');return}if(!Number.isFinite(v)||v<0)return;customDistances[[a,b].sort().join('|')]=v;closeModal('distanceModal');renderAll()}
function renderMatrix(){let q=(document.getElementById('distanceSearch')?.value||'').toLowerCase(),list=stations.filter(s=>s.name.toLowerCase().includes(q));document.getElementById('matrixWrap').innerHTML=`<table style="border-collapse:collapse;width:100%;font-size:11px;white-space:nowrap"><thead><tr><th style="text-align:left;position:sticky;left:0;background:#101922;padding:10px;border-bottom:1px solid var(--line)">FROM / TO</th>${list.map(s=>`<th style="padding:10px;border-bottom:1px solid var(--line);color:var(--cyan)">${esc(s.name)}</th>`).join('')}</tr></thead><tbody>${list.map(a=>`<tr><th style="text-align:left;position:sticky;left:0;background:#101922;padding:10px;border-bottom:1px solid #1d2b34">${esc(a.name)}</th>${list.map(b=>{let d=dist(a.id,b.id);return `<td title="${esc(a.name)} to ${esc(b.name)}" style="text-align:center;padding:10px;border-bottom:1px solid #1d2b34;color:${a.id===b.id?'var(--muted)':d==null?'#526674':'var(--text)'};background:${a.id===b.id?'#18242c':'transparent'}">${a.id===b.id?'—':d==null?'·':Number(d).toFixed(2)}</td>`}).join('')}</tr>`).join('')}</tbody></table><div class="note">* Distance values are from a community reference table; values added manually override the reference. Dot means no known value.</div>`}
function exportData(){let blob=new Blob([JSON.stringify({stations,routes,current,activeRoute,customDistances},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pyro-nav-backup.json';a.click();URL.revokeObjectURL(a.href)}
function validBackupData(data){if(!data||typeof data!=='object'||!validStationList(data.stations)||!validRouteList(data.routes)||typeof data.current!=='string'||typeof data.activeRoute!=='string'||!validDistances(data.customDistances))return false;const ids=new Set(data.stations.map(s=>s.id)),routeIds=new Set(data.routes.map(r=>r.id));if(data.current&&!ids.has(data.current)||data.activeRoute&&!routeIds.has(data.activeRoute))return false;if(data.routes.some(r=>r.stops.some(id=>!ids.has(id)||id===HOME_BASE_ID)||r.deliveryStationId!==undefined&&!ids.has(r.deliveryStationId)))return false;return Object.keys(data.customDistances).every(key=>{const pair=key.split('|');return pair.length===2&&pair[0]!==pair[1]&&ids.has(pair[0])&&ids.has(pair[1])})}
async function importBackup(file){if(!file)return;let data;try{data=JSON.parse(await file.text())}catch{alert('This file is not valid JSON. Your saved data was not changed.');return}if(!validBackupData(data)){alert('This backup has missing or invalid Pyro Nav data. Your saved data was not changed.');return}if(!confirm('Replace the current Pyro Nav data with this backup?'))return;const old={stations,routes,current,activeRoute,customDistances},oldIssue=persistenceIssue;stations=data.stations.map(s=>({...s}));if(!stations.some(s=>s.id===HOME_BASE_ID))stations.unshift({...initialStations[0]});const home=stations.find(s=>s.id===HOME_BASE_ID);home.name='Ruin Station';home.type='regular';home.status='done';routes=data.routes.map(r=>({...r,deliveryStationId:r.deliveryStationId||HOME_BASE_ID,stops:r.stops.filter(id=>id!==HOME_BASE_ID),completed:(r.completed||[]).filter(id=>id!==HOME_BASE_ID),runStarted:r.runStarted??((r.completed||[]).length>0||r.returnedHome===true),active:r.returnedHome===true?false:r.active??(r.id===data.activeRoute||(r.completed||[]).length>0),atHomeForDropoff:r.returnedHome===true?false:r.atHomeForDropoff??false,earlyDropoffs:r.earlyDropoffs||[]}));current=data.current;activeRoute=data.activeRoute;customDistances={...data.customDistances};persistenceWritable=true;persistenceIssue='';if(!save()){stations=old.stations;routes=old.routes;current=old.current;activeRoute=old.activeRoute;customDistances=old.customDistances;persistenceWritable=false;if(!persistenceIssue)persistenceIssue=oldIssue;renderAll();alert('The backup could not be saved to browser storage. The current in-memory data was restored.');return}const warning=document.getElementById('persistenceWarning');warning.hidden=true;warning.textContent='';renderAll();alert('Backup restored successfully.')}
function closeModal(id){document.getElementById(id).classList.remove('open');if(id==='featureRequestModal'){ownerInboxToken='';ownerRequests=[];document.getElementById('ownerToken').value='';document.getElementById('ownerRequests').innerHTML='';setOwnerStatus('','');if(feedbackTriggerElement&&document.contains(feedbackTriggerElement))feedbackTriggerElement.focus();feedbackTriggerElement=null}}
document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m.id)}));
document.addEventListener('keydown',event=>{const modal=document.querySelector('.modal.open');if(!modal)return;if(event.key==='Escape'){closeModal(modal.id);return}if(event.key!=='Tab')return;const focusable=Array.from(modal.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')).filter(element=>!element.closest('[hidden]')&&element.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
document.getElementById('featureRequestForm').addEventListener('input',()=>{if(document.getElementById('featureRequestStatus').classList.contains('is-success'))setFeedbackStatus('','')});
function resetData(){if(!confirm('Reset all Pyro Nav data to defaults? This does not affect other websites’ browser data.'))return;const keys=['pyroStations','pyroRoutes','pyroCurrent','pyroActiveRoute','pyroDistances'],previous={};try{keys.forEach(key=>previous[key]=localStorage.getItem(key))}catch{setPersistenceIssue('Browser storage could not be read, so the reset was cancelled and saved data was left untouched.');return}const removed=[];try{keys.forEach(key=>{localStorage.removeItem(key);removed.push(key)})}catch{let rollbackFailed=false;removed.forEach(key=>{try{if(previous[key]!==null)localStorage.setItem(key,previous[key])}catch{rollbackFailed=true}});setPersistenceIssue('Browser storage could not complete the reset. '+(rollbackFailed?'Some saved values may have changed.':'The app attempted to restore the saved data.'));return}persistenceWritable=true;persistenceIssue='';stations=initialStations.map(s=>({...s}));routes=[];current='ruin-station';activeRoute='';customDistances={};renderAll()}
document.querySelectorAll('input[name="uiAccent"]').forEach(input=>input.addEventListener('change',()=>changeUiPreference('accent',input.value)));
document.querySelectorAll('input[name="uiTextSize"]').forEach(input=>input.addEventListener('change',()=>changeUiPreference('textSize',input.value)));
function updateClock(){document.getElementById('clock').textContent=new Date().toLocaleTimeString([], {hour12:false})}
setInterval(updateClock,1000);updateClock();renderAll();
